// ---------- persistence ----------

type pItem struct {
	q    string
	args []any
}

var (
	pCh      = make(chan pItem, 1<<20)
	pPending atomic.Int64
)

func persist(q string, args ...any) {
	pPending.Add(1)
	pCh <- pItem{q, args}
}

func flushPersist() {
	for pPending.Load() > 0 {
		time.Sleep(5 * time.Millisecond)
	}
}

func persistWorker() {
	batch := make([]pItem, 0, 256)
	for {
		it := <-pCh
		batch = append(batch[:0], it)
	drain:
		for len(batch) < 256 {
			select {
			case it := <-pCh:
				batch = append(batch, it)
			default:
				break drain
			}
		}
		for {
			err := execBatch(batch)
			if err == nil {
				break
			}
			log.Printf("persist error: %v", err)
			if isFatalSQL(err) {
				// execute individually, skipping bad ones
				for _, b := range batch {
					if _, err := db.Exec(b.q, b.args...); err != nil {
						log.Printf("persist drop: %v %s", err, b.q)
					}
				}
				break
			}
			time.Sleep(200 * time.Millisecond)
		}
		pPending.Add(-int64(len(batch)))
	}
}

func isFatalSQL(err error) bool {
	_, ok := err.(*mysql.MySQLError)
	return ok
}

func execBatch(batch []pItem) error {
	if len(batch) == 1 {
		_, err := db.Exec(batch[0].q, batch[0].args...)
		return err
	}
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	for _, b := range batch {
		if _, err := tx.Exec(b.q, b.args...); err != nil {
			tx.Rollback()
			return err
		}
	}
	return tx.Commit()
}

