	for _, x := range lts {
		if l := lsMap[x.l]; l != nil {
			l.tags = append(l.tags, tByID[x.t])
		}
	}
	sort.SliceStable(lts, func(i, j int) bool { return lts[i].l < lts[j].l })
	for _, x := range lts {
		if l := lsMap[x.l]; l != nil {
			tIdx[x.t] = append(tIdx[x.t], l)
		}
	}

