		}
		c.user = uByID[uid]
		c.ls = lsMap[lid]
		if c.user == nil || c.ls == nil {
			continue
		}
		cMap[c.ID] = c
		c.ls.comments = append(c.ls.comments, c)
		c.ls.tipSum += c.Tip
		c.ls.owner.recvTips += c.Tip
		c.ls.owner.recvComments++
		tt += c.Tip
	}
