	l.owner.emoji[rc.Emoji]++
	persist("INSERT INTO reactions (id, user_id, livestream_id, emoji_name, created_at) VALUES (?, ?, ?, ?, ?)", rc.ID, uid, lid, rc.Emoji, now)
