	mu.RLock()
	l := livestreams[lid]
	if l == nil {
		mu.RUnlock()
		writeErr(w, 400, "cannot get stats of not found livestream")
		return
	}
	my := l.reactCnt + l.tipSum
	var rank int64 = 1
	for _, o := range lsOrder {
