		if s > my || (s == my && o.ID > l.ID) {
			rank++
		}
	}
	resp := map[string]any{
		"rank":            rank,
		"viewers_count":   l.viewerCnt,
		"total_reactions": l.reactCnt,
		"total_reports":   int64(len(l.reports)),
		"max_tip":         l.maxTip(),
	}
	mu.RUnlock()
	writeJSON(w, 200, resp)
}

